// formatV2GroupedGoldenPath is a checked-in VECTOR-FREE grouped (0x02)
// cohort: format_v1.pulse deduplicated with one indexed group. It was
// generated by the writer as it stood BEFORE the VECTORS section existed,
// so the byte comparison below proves adding vectors left every
// vector-free grouped write byte-identical. Never regenerate it to make
// a failure pass — a failure is a compatibility break.
const formatV2GroupedGoldenPath = "../../encoding/testdata/format_v2_grouped.pulse"

func groupedGoldenSpecs() []GroupSpec {
	return []GroupSpec{{Kind: encoding.GroupKindIndexed, Members: []string{"label", "n_u16"}}}
}

// TestFormatV2GroupedGolden_ByteIdentical: deduplicating the 0x01
// golden still emits the checked-in grouped bytes, and those bytes still
// decode to the 0x01 golden's rows.
func TestFormatV2GroupedGolden_ByteIdentical(t *testing.T) {
	t.Parallel()

	v1, err := os.ReadFile(formatV1GoldenPath)
	if err != nil {
		t.Fatal(err)
	}
	var fresh bytes.Buffer
	if _, _, err := DedupCohort(&fresh, bytes.NewReader(v1), groupedGoldenSpecs()); err != nil {
		t.Fatalf("DedupCohort: %v", err)
	}
	if *updateFormatGolden {
		if err := os.WriteFile(formatV2GroupedGoldenPath, fresh.Bytes(), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	golden, err := os.ReadFile(formatV2GroupedGoldenPath)
	if err != nil {
		t.Fatalf("reading %s: %v", formatV2GroupedGoldenPath, err)
	}
	if golden[encoding.HeaderSize-1] != encoding.FormatVersionV2 {
		t.Fatalf("grouped golden version = 0x%02x, want 0x02", golden[encoding.HeaderSize-1])
	}
	if !bytes.Equal(fresh.Bytes(), golden) {
		t.Fatal("the current writer no longer emits the checked-in vector-free grouped 0x02 bytes")
	}
	s, _, err := ReadPreamble(bytes.NewReader(golden))
	if err != nil {
		t.Fatal(err)
	}
	if s.HasVectors() || !s.HasGroups() {
		t.Fatalf("grouped golden: HasVectors=%v HasGroups=%v", s.HasVectors(), s.HasGroups())
	}
	_, flatRows := decodeAll(t, v1)
	_, groupedRows := decodeAll(t, golden)
	if !reflect.DeepEqual(flatRows, groupedRows) {
		t.Fatalf("grouped golden decodes differently from its 0x01 source")
	}
}

// vecCohortSchema: scalars around a vec_f32 and a nullable, fully
// described vec_f64.
func vecCohortSchema() *encoding.Schema {
	return &encoding.Schema{Fields: []encoding.Field{
		{Name: "id", Type: encoding.FieldTypeU16},
		{Name: "emb", Type: encoding.FieldTypeVecF32},
		{Name: "rating", Type: encoding.FieldTypeVecF64, Nullable: true},
		{Name: "tail", Type: encoding.FieldTypeU8},
	}, Vectors: []encoding.VectorField{
		{FieldIndex: 1, Dim: 2},
		{FieldIndex: 2, Dim: 3, Kind: encoding.VectorKindScale, HasScale: true, ScaleMin: 1, ScaleMax: 5, Labels: []string{"x", "y", "z"}},
	}}
}

var vecCohortRows = []struct {
	id     uint16
	emb    []float64
	rating []float64 // nil = null
	tail   uint8
}{
	{1, []float64{0.5, -1}, []float64{1, 2.5, 5}, 9},
	{2, []float64{2, 4}, nil, 8},
	{3, []float64{-0.25, 8}, []float64{math.NaN(), 3, 4}, 7},
}

// vecCohortFile writes a vector cohort through WritePreamble and the
// encoding vector API: the null vector is a zeroed stride plus its bit.
func vecCohortFile(t *testing.T, s *encoding.Schema) []byte {
	t.Helper()
	var b bytes.Buffer
	if err := WritePreamble(&b, s); err != nil {
		t.Fatalf("WritePreamble: %v", err)
	}
	must := func(err error) {
		t.Helper()
		if err != nil {
			t.Fatal(err)
		}
	}
	for _, r := range vecCohortRows {
		must(encoding.WriteFieldValue(&b, encoding.FieldTypeU16, uint64(r.id)))
		must(encoding.WriteVector(&b, encoding.FieldTypeVecF32, 2, r.emb))
		must(encoding.WriteVector(&b, encoding.FieldTypeVecF64, 3, r.rating))
		must(encoding.WriteFieldValue(&b, encoding.FieldTypeU8, uint64(r.tail)))
		bm := make([]byte, s.BitmapByteSize())
		if r.rating == nil {
			encoding.BitmapSetNull(bm, 2)
		}
		must(encoding.WriteBitmap(&b, bm))
	}
	return b.Bytes()
}

// TestVectorCohort_StoreAndRead: a vector cohort is written at 0x02,
// reads back with its metadata, and its fixed stride (2 + 8 + 24 + 1 +
// 1 bitmap = 36) locates every record and every vector cell.
func TestVectorCohort_StoreAndRead(t *testing.T) {
	t.Parallel()

	s := vecCohortSchema()
	data := vecCohortFile(t, s)
	if data[encoding.HeaderSize-1] != encoding.FormatVersionV2 {
		t.Fatalf("version = 0x%02x, want 0x02", data[encoding.HeaderSize-1])
	}
	r := bytes.NewReader(data)
	got, v, err := ReadPreamble(r)
	if err != nil {
		t.Fatalf("ReadPreamble: %v", err)
	}
	if v != encoding.FormatVersionV2 || !reflect.DeepEqual(got.Vectors, s.Vectors) {
		t.Fatalf("version/vectors = 0x%02x / %+v", v, got.Vectors)
	}
	if got.RecordByteSize() != 36 {
		t.Fatalf("stride = %d, want 36", got.RecordByteSize())
	}
	if r.Len() != 3*36 {
		t.Fatalf("record region = %d bytes, want %d", r.Len(), 3*36)
	}
	loc, err := encoding.NewRecordLocator(bytes.NewReader(data), got)
	if err != nil {
		t.Fatal(err)
	}
	if loc.TotalRecords != 3 {
		t.Fatalf("TotalRecords = %d, want 3", loc.TotalRecords)
	}
	for i, want := range vecCohortRows {
		rec := data[loc.Offset(uint64(i)):][:36]
		if id := binary.LittleEndian.Uint16(rec); id != want.id {
			t.Errorf("row %d id = %d", i, id)
		}
		emb, err := encoding.VectorFromBytes(rec[2:], encoding.FieldTypeVecF32, 2, nil)
		if err != nil || !reflect.DeepEqual(emb, want.emb) {
			t.Errorf("row %d emb = %v, %v", i, emb, err)
		}
		rating, err := encoding.VectorFromBytes(rec[10:], encoding.FieldTypeVecF64, 3, nil)
		if err != nil {
			t.Fatal(err)
		}
		null := encoding.BitmapIsNull(rec[35:], 2)
		switch {
		case want.rating == nil:
			if !null || !bytes.Equal(rec[10:34], make([]byte, 24)) {
				t.Errorf("row %d: null vector must be a zeroed stride + bit (null=%v bytes=%v)", i, null, rec[10:34])
			}
		case null:
			t.Errorf("row %d: present vector marked null", i)
		default:
			for e := range want.rating {
				if math.Float64bits(rating[e]) != math.Float64bits(want.rating[e]) {
					t.Errorf("row %d rating[%d] = %v, want %v", i, e, rating[e], want.rating[e])
				}
			}
		}
		if rec[34] != want.tail {
			t.Errorf("row %d tail = %d", i, rec[34])
		}
	}
	// Re-writing the decoded schema reproduces the preamble exactly.
	var again bytes.Buffer
	if err := WritePreamble(&again, got); err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(again.Bytes(), data[:len(data)-3*36]) {
		t.Fatal("decoded vector schema does not re-write byte-identically")
	}
}

// extSection is one tagged section of a 0x02 extension block.
type extSection struct {
	tag   uint16
	flags uint8
	body  []byte
}

// splitExtension cuts a 0x02 file into the bytes before its extension
// block, the block's sections, and the record region. The descriptor
// length is measured from a 0x01 twin whose vec fields are re-typed f64
// (same descriptor bytes) and whose groups and vectors are dropped.
func splitExtension(t *testing.T, data []byte, s *encoding.Schema) (pre []byte, secs []extSection, recs []byte) {
	t.Helper()
	twin := &encoding.Schema{Fields: append([]encoding.Field(nil), s.Fields...)}
	for i := range twin.Fields {
		if twin.Fields[i].Type.IsVector() {
			twin.Fields[i].Type = encoding.FieldTypeF64
		}
	}
	var d bytes.Buffer
	if err := encoding.WriteSchema(&d, twin); err != nil {
		t.Fatal(err)
	}
	at := encoding.HeaderSize + d.Len()
	le := binary.LittleEndian
	extLen := int(le.Uint64(data[at:]))
	payload := data[at+8 : at+8+extLen]
	n := int(le.Uint16(payload))
	p := payload[2:]
	for i := 0; i < n; i++ {
		sec := extSection{tag: le.Uint16(p), flags: p[2]}
		l := int(le.Uint64(p[3:]))
		sec.body = p[11 : 11+l]
		p = p[11+l:]
		secs = append(secs, sec)
	}
	return data[:at], secs, data[at+8+extLen:]
}

func joinExtension(pre []byte, secs []extSection, recs []byte) []byte {
	le := binary.LittleEndian
	payload := le.AppendUint16(nil, uint16(len(secs)))
	for _, s := range secs {
		payload = le.AppendUint16(payload, s.tag)
		payload = append(payload, s.flags)
		payload = le.AppendUint64(payload, uint64(len(s.body)))
		payload = append(payload, s.body...)
	}
	out := append(append([]byte(nil), pre...), le.AppendUint64(nil, uint64(len(payload)))...)
	out = append(out, payload...)
	return append(out, recs...)
}

// TestVectorCohort_Compat covers the compatibility proofs: (a) a vector
// cohort whose VECTORS section is stripped — as a 0x02 file with no
// section, or rewritten as 0x01 — is refused (its vec fields have no
// width), never mis-strided; (b) the section re-tagged to a tag this
// binary does not know, still REQUIRED, is ENCODING_INVALID — exactly
// what a pre-vector binary does with the real tag 2; an optional
// unknown tag is skipped, so the file still fails on (a)'s rule.
func TestVectorCohort_Compat(t *testing.T) {
	t.Parallel()

	s := vecCohortSchema()
	data := vecCohortFile(t, s)
	pre, secs, recs := splitExtension(t, data, s)
	if len(secs) != 1 || secs[0].tag != 2 || secs[0].flags != 1 {
		t.Fatalf("sections = %+v, want one REQUIRED tag-2 section", secs)
	}
	if !bytes.Equal(joinExtension(pre, secs, recs), data) {
		t.Fatal("split/join helper is not lossless")
	}
	coded := func(err error) *errors.CodedError {
		var ce *errors.CodedError
		if !stderrors.As(err, &ce) || ce.Code != errors.ENCODING_INVALID {
			t.Fatalf("err = %v, want ENCODING_INVALID", err)
		}
		return ce
	}

	// (a) stripped, still 0x02.
	_, _, err := ReadPreamble(bytes.NewReader(joinExtension(pre, nil, recs)))
	if ce := coded(err); !strings.Contains(ce.Message, "no VECTORS entry") || ce.Details["field"] != "emb" {
		t.Fatalf("stripped 0x02: %v %v", ce.Message, ce.Details)
	}
	// (a) stripped and rewritten as 0x01.
	v1 := append(append([]byte(nil), pre...), recs...)
	v1[encoding.HeaderSize-1] = encoding.FormatVersionV1
	_, _, err = ReadPreamble(bytes.NewReader(v1))
	if ce := coded(err); !strings.Contains(ce.Message, "no VECTORS entry") {
		t.Fatalf("stripped 0x01: %v", ce.Message)
	}

	// (b) re-tagged, REQUIRED.
	retag := []extSection{{tag: 0x0200, flags: 1, body: secs[0].body}}
	_, _, err = ReadPreamble(bytes.NewReader(joinExtension(pre, retag, recs)))
	if ce := coded(err); !strings.Contains(ce.Message, "required section") || ce.Details["tag"] != uint16(0x0200) {
		t.Fatalf("re-tagged: %v %v", ce.Message, ce.Details)
	}
	// Re-tagged OPTIONAL: skipped, so the vec fields are uncovered.
	retag[0].flags = 0
	_, _, err = ReadPreamble(bytes.NewReader(joinExtension(pre, retag, recs)))
	if ce := coded(err); !strings.Contains(ce.Message, "no VECTORS entry") {
		t.Fatalf("re-tagged optional: %v", ce.Message)
	}
	// VECTORS marked optional is still read (a known tag is understood).
	opt := []extSection{{tag: 2, flags: 0, body: secs[0].body}}
	if _, _, err := ReadPreamble(bytes.NewReader(joinExtension(pre, opt, recs))); err != nil {
		t.Fatalf("known tag without the REQUIRED bit: %v", err)
	}
}

// groupedVecSchema puts the vec_f64 field in a constant group, so the
// GROUPS entry width (8 × dim) is only checkable once VECTORS is known.
func groupedVecSchema() *encoding.Schema {
	s := &encoding.Schema{Fields: []encoding.Field{
		{Name: "id", Type: encoding.FieldTypeU16},
		{Name: "v", Type: encoding.FieldTypeVecF64},
	}, Vectors: []encoding.VectorField{{FieldIndex: 1, Dim: 3}}}
	entry := make([]byte, 24)
	if err := encoding.PutVector(entry, encoding.FieldTypeVecF64, 3, []float64{1, 2, 3}); err != nil {
		panic(err)
	}
	s.Groups = []encoding.Group{{Kind: encoding.GroupKindConstant, Members: []encoding.GroupMember{{Field: 1}}, Entries: entry}}
	return s
}

// TestVectorCohort_SectionOrder: the writer emits GROUPS (tag 1) before
// VECTORS (tag 2), so a group over a vec member must have its entry
// width checked AFTER the vectors are read; the reader accepts the
// sections in either disk order with an identical result, and still
// refuses a declared entry width that disagrees with the dim.
func TestVectorCohort_SectionOrder(t *testing.T) {
	t.Parallel()

	s := groupedVecSchema()
	var b bytes.Buffer
	if err := WritePreamble(&b, s); err != nil {
		t.Fatalf("WritePreamble: %v", err)
	}
	b.Write([]byte{5, 0}) // one physical row: the id
	data := b.Bytes()
	pre, secs, recs := splitExtension(t, data, s)
	if len(secs) != 2 || secs[0].tag != 1 || secs[1].tag != 2 {
		t.Fatalf("sections not in tag order: %+v", secs)
	}
	inOrder, _, err := ReadPreamble(bytes.NewReader(data))
	if err != nil {
		t.Fatalf("GROUPS-then-VECTORS: %v", err)
	}
	reversed, _, err := ReadPreamble(bytes.NewReader(joinExtension(pre, []extSection{secs[1], secs[0]}, recs)))
	if err != nil {
		t.Fatalf("VECTORS-then-GROUPS: %v", err)
	}
	if !reflect.DeepEqual(inOrder.Vectors, reversed.Vectors) || !reflect.DeepEqual(inOrder.Groups, reversed.Groups) {
		t.Fatal("disk order changed the decoded schema")
	}
	if inOrder.GroupEntryWidth(0) != 24 || inOrder.RecordByteSize() != 2 {
		t.Fatalf("entry width / stride = %d / %d, want 24 / 2", inOrder.GroupEntryWidth(0), inOrder.RecordByteSize())
	}
	// A dim that disagrees with the stored entry width is refused in
	// either order. The VECTORS body is: u16 count, u16 field_index,
	// u16 dim, u8 flags — dim at offset 4.
	bad := extSection{tag: 2, flags: 1, body: append([]byte(nil), secs[1].body...)}
	binary.LittleEndian.PutUint16(bad.body[4:], 4)
	for _, order := range [][]extSection{{secs[0], bad}, {bad, secs[0]}} {
		_, _, err := ReadPreamble(bytes.NewReader(joinExtension(pre, order, recs)))
		var ce *errors.CodedError
		if !stderrors.As(err, &ce) || ce.Code != errors.ENCODING_INVALID || !strings.Contains(ce.Message, "entry width") {
			t.Fatalf("dim/entry-width mismatch: err = %v", err)
		}
	}
}

// TestVectorCohort_WriteRefusesUncovered: a schema with a vec field and
// no VECTORS entry cannot be written at any version — it would carry a
// field of unknown width.
func TestVectorCohort_WriteRefusesUncovered(t *testing.T) {
	t.Parallel()

	s := vecCohortSchema()
	s.Vectors = nil
	if s.RequiredFormatVersion() != encoding.FormatVersionV1 {
		t.Fatal("no vectors declared should not by itself require 0x02")
	}
	for _, v := range encoding.SupportedFormatVersions() {
		var b bytes.Buffer
		err := writePreambleVersion(&b, s, v)
		if !errors.HasCode(err, errors.ENCODING_INVALID) {
			t.Fatalf("version 0x%02x: err = %v, want ENCODING_INVALID", v, err)
		}
	}
	if err := encoding.WriteSchema(&bytes.Buffer{}, s); !errors.HasCode(err, errors.ENCODING_INVALID) {
		t.Fatalf("WriteSchema: err = %v, want ENCODING_INVALID", err)
	}
}

// TestSchemaCopies_CarryVectors: every schema copy a downstream path
// takes keeps the vec fields' dims, so no copy can size a vec field at 0.
func TestSchemaCopies_CarryVectors(t *testing.T) {
	t.Parallel()

	s := vecCohortSchema()
	want := s.RecordByteSize()
	enc, err := NewGroupEncoder(s, nil)
	if err != nil {
		t.Fatal(err)
	}
	joined, err := JoinedSchema(s, s, "r_")
	if err != nil {
		t.Fatal(err)
	}
	for name, got := range map[string]int{
		"cloneSchema":       cloneSchema(s).RecordByteSize(),
		"GroupEncoder":      enc.Schema().RecordByteSize(),
		"Logical(grouped)":  groupedVecSchema().Logical().FieldWidth(1),
		"JoinedSchema left": joined.FieldWidth(2),
	} {
		w := want
		switch name {
		case "Logical(grouped)":
			w = 24
		case "JoinedSchema left":
			w = 24
		}
		if got != w {
			t.Errorf("%s: width %d, want %d", name, got, w)
		}
	}
	if got := joined.FieldWidth(4 + 2); got != 24 {
		t.Errorf("JoinedSchema right vec width = %d, want 24 (index shifted past the left fields)", got)
	}
	if v, ok := joined.Vector(6); !ok || !reflect.DeepEqual(v.Labels, []string{"x", "y", "z"}) {
		t.Errorf("JoinedSchema right vec metadata = %+v, %v", v, ok)
	}
	c := cloneSchema(s)
	c.Vectors[1].Labels[0] = "mutated"
	if s.Vectors[1].Labels[0] != "x" {
		t.Error("cloneSchema aliases vector labels")
	}
}
